const fs = require('fs');
const path = require('path');
const { venues, hydrate } = require('./build_slides');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'outputs', 'bucharest-exhibitions-editor.html');

function editorData() {
  return venues.map(v => ({
    name: v.name,
    sub: v.sub,
    hoursNote: v.hoursNote || '',
    hours: [...v.hours],
    admission: v.admission || '',
    exhibitions: v.exhibitions.map(ex => ({
      title: ex.title,
      dates: ex.dates,
      price: ex.price || '',
      href: ex.href || '',
      description: '',
      images: [...ex.images],
    })),
  }));
}

